public class NDXProdTable2ProdIdent extends common
{
}

Method.Source:
/// <summary>
/// PaffH 05.08.24
/// </summary>
/// <param name = "_filterProdId">ProdId</param>
/// <param name = "_checkMax">int</param>
static server void checkProdTable(ProdId _filterProdId = '', int _checkMax = 0)
{
    Counter anz = 0;
    ProdId prodIdStart, prodIdEnd;
    NDXHasPhantomBOM nDXHasPhantomBOM;
    NDXPhantomOprNumAdd nDXPhantomOprNumAdd;
    try
    {
        Query q = new Query();
        QueryBuildDataSource qbdsProdTable = q.addDataSource(tableNum(ProdTable));
        if (_filterProdId)
        {
            qbdsProdTable.addRange(fieldNum(ProdTable, ProdId)).value(_filterProdId);
        }
        qbdsProdTable.addOrderByField(fieldNum(ProdTable, ProdId), SortOrder::Descending);
        QueryRun qr = new QueryRun(q);
        while (qr.next())
        {
            ProdTable prodTable = qr.get(tableNum(ProdTable));
            boolean doUpdate = false;
            if (_checkMax && anz > _checkMax)
            {
                break;
            }
            if (!anz)
            {
                prodIdStart = prodTable.ProdId;
            }
            prodIdEnd = prodTable.ProdId;

            // check Phantom
            [nDXHasPhantomBOM, nDXPhantomOprNumAdd] = NDXProdIdent::checkPhantom(prodTable.ItemId, false);
            doUpdate = doUpdate || nDXHasPhantomBOM;

            // check ProdIdent
            QueryRun qrTechnique = new QueryRun(NDXProdIdent::queryFromProdIdentTechnique(prodTable.ItemId));
            qrTechnique.next();
            NDXProdIdentProcedureTable nDXProdIdentProcedureTable = qrTechnique.get(tableNum(NDXProdIdentProcedureTable));
            NDXHasBTLabelDefinition hasBTLabelDefinition = nDXProdIdentProcedureTable != null;
            doUpdate = doUpdate || hasBTLabelDefinition;

            // check PA with BT-label
            NDXBTPAWithBTLabelRef bTPAWithBTLabelRef = NDXProdIdentControlPanel::existsProdTable(prodTable.ProdId);
            doUpdate = doUpdate || bTPAWithBTLabelRef;

            if (doUpdate)
            {
                NDXProdTable2ProdIdent nDXProdTable2ProdIdent = NDXProdTable2ProdIdent::findByProdTable(prodTable.RecId, true);
                if (!nDXProdTable2ProdIdent)
                {
                    nDXProdTable2ProdIdent.ProdTable = prodTable.RecId;
                }
                nDXProdTable2ProdIdent.HasPhantomBOM = nDXHasPhantomBOM;
                nDXProdTable2ProdIdent.PhantomOprNumAdd = nDXPhantomOprNumAdd;
                nDXProdTable2ProdIdent.HasBTLabelDefinition = hasBTLabelDefinition;
                nDXProdTable2ProdIdent.BTPAWithBTLabelRef = bTPAWithBTLabelRef;
                ttsbegin;
                nDXProdTable2ProdIdent.write();
                ttscommit;
            }
            ++anz;
        }
        if (anz > 1)
        {
            Info(strFmt("@NDX:NDXcheckProdTableInfo01", anz, prodIdStart, prodIdEnd));
        }
    }
    catch
    {
        error("@NDX:NDXNDXProdTable2ProdIdentCheckProdTableError");
    }
}

/// <summary>
/// PaffH 05.08.24
/// </summary>
/// <param name = "_prodId">ProdId</param>
/// <param name = "_update">boolean</param>
/// <returns>NDXProdTable2ProdIdent</returns>
static NDXProdTable2ProdIdent find(ProdId _prodId, boolean _update = false)
{
    NDXProdTable2ProdIdent nDXProdTable2ProdIdent;
    nDXProdTable2ProdIdent.selectForUpdate(_update);
    select firstonly nDXProdTable2ProdIdent
        where nDXProdTable2ProdIdent.ProdTable == ProdTable::find(_prodId).RecId;
    return nDXProdTable2ProdIdent;
}

/// <summary>
/// PaffH 05.08.24
/// </summary>
/// <param name = "_ProdTableRecId">RecId ProdTable</param>
/// <param name = "_update">boolean</param>
/// <returns>NDXProdTable2ProdIdent</returns>
static NDXProdTable2ProdIdent findByProdTable(RefRecId _ProdTableRecId, boolean _update = false)
{
    NDXProdTable2ProdIdent nDXProdTable2ProdIdent;
    nDXProdTable2ProdIdent.selectForUpdate(_update);
    select firstonly nDXProdTable2ProdIdent
        where nDXProdTable2ProdIdent.ProdTable == _ProdTableRecId;
    return nDXProdTable2ProdIdent;
}
